export function Portfolio({
  name = "{{name}}",
  lead = "{{lead}}",
  projectsShown = {{projectsShown}},
  onTrack = {{onTrack}},
  accent = "{{accent}}",
}) {
  const projects = ["Checkout Redesign", "Onboarding Revamp", "Billing Migration"].slice(0, projectsShown);
  return (
    <section aria-labelledby="portfolio-heading-react" style={{ maxWidth: 480, padding: "18px 20px", borderRadius: 12, background: "#FAF7F2", border: "1px solid #24143022", boxSizing: "border-box", font: "14px/1.4 system-ui, sans-serif", color: "#241430" }}>
      <header style={{ borderLeft: "3px solid " + accent, paddingLeft: 10, marginBottom: 10 }}>
        <h3 id="portfolio-heading-react" style={{ margin: 0, fontSize: 16, fontWeight: 700 }}>{name}</h3>
        <p style={{ margin: "2px 0 0", fontSize: 12.5, color: "#241430b3" }}>Led by {lead}</p>
      </header>
      <p style={{ margin: "0 0 10px", fontSize: 13, fontWeight: 600 }}>{projectsShown} projects &middot; {onTrack} on track</p>
      <ul style={{ listStyle: "none", margin: 0, padding: 0, display: "flex", flexDirection: "column", gap: 8 }}>
        {projects.map((p) => (
          <li key={p} style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 13.5, padding: "8px 10px", borderRadius: 8, background: "#24143008" }}>
            <span style={{ width: 8, height: 8, borderRadius: "50%", background: accent, flexShrink: 0 }} />
            {p}
          </li>
        ))}
      </ul>
    </section>
  );
}
